import 'package:flutter/material.dart';import 'package:go_router/go_router.dart';import 'package:platform_core_frontend/features/super_admin/models/admin_masjid_request_model.dart';import 'package:platform_core_frontend/features/super_admin/presentation/widgets_common.dart';
class AdminMasjidRequestCard extends StatelessWidget{const AdminMasjidRequestCard({super.key,required this.item,this.onApprove,this.onReject});final AdminMasjidRequestModel item;final VoidCallback? onApprove,onReject;@override Widget build(BuildContext c)=>Card(child:ListTile(title:Text(item.masjidName??'Masjid request'),subtitle:Text('${item.requesterName??'-'} • ${item.requesterPhone??'-'}\n${[item.address,item.locality,item.district,item.state,item.country].where((e)=>e!=null&&e.isNotEmpty).join(', ')}'),isThreeLine:true,trailing:Wrap(spacing:8,runSpacing:8,children:[AdminStatusChip(item.status),TextButton(onPressed:()=>c.go('/super-admin/requests/${item.id}',extra:item),child:const Text('View')),if(item.status?.toUpperCase()=='PENDING')TextButton(onPressed:onApprove,child:const Text('Approve')),if(item.status?.toUpperCase()=='PENDING')TextButton(onPressed:onReject,child:const Text('Reject'))])));}
